import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import axios from "axios";
import JobCard from "./JobCard";

export default function JobList() {
  const navigate = useNavigate();
  const [jobs, setJobs] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    fetchJobs();
  }, []);

  const fetchJobs = async () => {
    try {
      const response = await axios.get("http://localhost:5000/api/jobs");
      setJobs(response.data);
      setLoading(false);
    } catch (err) {
      console.error("Error fetching jobs:", err);
      setError("Failed to load job listings. Please try again later.");
      setLoading(false);
    }
  };

  if (loading) {
    return (
      <div style={styles.loadingContainer}>
        <div style={styles.loader}></div>
        <p>Loading available positions...</p>
      </div>
    );
  }

  if (error) {
    return (
      <div style={styles.errorContainer}>
        <h2>⚠️ {error}</h2>
        <button style={styles.retryBtn} onClick={fetchJobs}>
          Retry
        </button>
      </div>
    );
  }

  return (
    <div style={styles.container}>
      <div style={styles.header}>
        <h1 style={styles.title}>Career Opportunities</h1>
        <p style={styles.subtitle}>
          Join our team and grow your career with exciting opportunities
        </p>
        <div style={styles.statsBar}>
          <div style={styles.statItem}>
            <span style={styles.statNumber}>{jobs.length}</span>
            <span style={styles.statLabel}>Open Positions</span>
          </div>
        </div>
      </div>

      {jobs.length === 0 ? (
        <div style={styles.noJobsContainer}>
          <h2>No positions available at the moment</h2>
          <p>Please check back later for new opportunities</p>
        </div>
      ) : (
        <div style={styles.jobGrid}>
          {jobs.map((job) => (
            <JobCard
              key={job._id}
              job={job}
              onClick={() => navigate(`/job/${job._id}`)}
            />
          ))}
        </div>
      )}
    </div>
  );
}

const styles = {
  container: {
    minHeight: "100vh",
    background: "linear-gradient(135deg, #667eea 0%, #764ba2 100%)",
    padding: "40px 20px",
  },
  header: {
    maxWidth: "1200px",
    margin: "0 auto 40px",
    textAlign: "center",
    color: "#fff",
  },
  title: {
    fontSize: "48px",
    fontWeight: "700",
    marginBottom: "10px",
    textShadow: "2px 2px 4px rgba(0,0,0,0.2)",
  },
  subtitle: {
    fontSize: "18px",
    marginBottom: "30px",
    opacity: 0.95,
  },
  statsBar: {
    display: "flex",
    justifyContent: "center",
    gap: "40px",
    marginTop: "20px",
  },
  statItem: {
    display: "flex",
    flexDirection: "column",
    alignItems: "center",
  },
  statNumber: {
    fontSize: "36px",
    fontWeight: "700",
  },
  statLabel: {
    fontSize: "14px",
    opacity: 0.9,
  },
  jobGrid: {
    maxWidth: "1200px",
    margin: "0 auto",
    display: "grid",
    gridTemplateColumns: "repeat(auto-fill, minmax(350px, 1fr))",
    gap: "25px",
  },
  loadingContainer: {
    display: "flex",
    flexDirection: "column",
    alignItems: "center",
    justifyContent: "center",
    height: "100vh",
    background: "linear-gradient(135deg, #667eea 0%, #764ba2 100%)",
    color: "#fff",
  },
  loader: {
    width: "50px",
    height: "50px",
    border: "5px solid rgba(255,255,255,0.3)",
    borderTop: "5px solid #fff",
    borderRadius: "50%",
    animation: "spin 1s linear infinite",
  },
  errorContainer: {
    display: "flex",
    flexDirection: "column",
    alignItems: "center",
    justifyContent: "center",
    height: "100vh",
    background: "linear-gradient(135deg, #667eea 0%, #764ba2 100%)",
    color: "#fff",
    textAlign: "center",
    padding: "20px",
  },
  retryBtn: {
    marginTop: "20px",
    padding: "12px 30px",
    background: "#fff",
    color: "#667eea",
    border: "none",
    borderRadius: "8px",
    fontSize: "16px",
    fontWeight: "600",
    cursor: "pointer",
  },
  noJobsContainer: {
    maxWidth: "600px",
    margin: "0 auto",
    textAlign: "center",
    background: "#fff",
    padding: "60px 40px",
    borderRadius: "12px",
    boxShadow: "0 10px 30px rgba(0,0,0,0.2)",
  },
};
